const picture={type:'image/png',base64:'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aGQAAAABJRU5ErkJggg=='};
function readyData(){return Object.fromEntries(PREPARATION_KEYS.map(key=>[key,{status:'Ready',...(['equipment','parts'].includes(key)?{items:[{itemId:key+'-1',name:key,pendingImage:picture}]}:{evidence:[{pendingImage:picture}]})}]));}
test('V2 readiness requires actual category evidence and content, never only six Ready dropdowns',async()=>{
 const f=fixture(),p=await f.service.create(baseInput);let saved=await f.prepare(p.projectId,{data:Object.fromEntries(PREPARATION_KEYS.map(key=>[key,{status:'Ready'}]))});assert.equal(saved.preparationReadiness.count,0);assert.equal(saved.preparationStatus,'In Progress');assert.ok(saved.preparationReadiness.categories.workstation.errors.includes('Workstation photo is required before this section can be Ready.'));
 saved=await f.prepare(p.projectId,{data:{workstation:{evidence:[{pendingImage:picture}]}}});assert.equal(saved.preparationReadiness.count,1);assert.equal(saved.preparationReadiness.categories.workstation.valid,true);assert.equal(saved.preparationData.schemaVersion,2);assert.doesNotMatch(JSON.stringify(saved),/private-token|file_token|pendingImage|base64/);
 await assert.rejects(f.service.status(p.projectId,{projectStatus:'Activating'}),e=>e.code==='PREPARATION_VALIDATION_FAILED'&&e.details.errors.length>1);
 saved=await f.ready(p.projectId);assert.equal(saved.preparationReadiness.count,6);assert.equal(saved.preparationStatus,'Ready');await f.service.status(p.projectId,{projectStatus:'Activating'});
});
test('Feishu token-only update responses are re-read before returning authoritative picture readiness',async()=>{const f=fixture(),p=await f.service.create(baseInput),update=f.records.updateRecord;f.records.updateRecord=async args=>{await update(args);return {record_id:args.recordId,fields:args.fields};};const saved=await f.ready(p.projectId);assert.equal(saved.preparationReadiness.count,6);assert.equal(saved.workstationAssets.count,1);assert.doesNotMatch(JSON.stringify(saved),/private-token|file_token/);});
for(const category of ['equipment','parts'])test(`${category} stable named items each require their own picture; replacement/removal is isolated`,async()=>{
 const f=fixture(),p=await f.service.create(baseInput);const items=[{itemId:'item-a',name:'A',note:''},{itemId:'item-b',name:'B',note:''}];
 let saved=await f.prepare(p.projectId,{data:{[category]:{status:'Ready',items:[items[0]]}}});assert.equal(saved.preparationReadiness.categories[category].valid,false);
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[0],pendingImage:picture}]}}});assert.equal(saved.preparationReadiness.categories[category].valid,true);const first=saved.preparationData[category].items[0];
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[0],assetId:first.assetId},items[1]]}}});assert.equal(saved.preparationReadiness.categories[category].valid,false);
 await assert.rejects(f.prepare(p.projectId,{data:{[category]:{items:items.map(item=>({...item,assetId:first.assetId}))}}}),e=>e.code==='UNKNOWN_PROJECT_ASSET');
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[0],assetId:first.assetId},{...items[1],pendingImage:picture}]}}});assert.equal(saved.preparationReadiness.categories[category].valid,true);const second=saved.preparationData[category].items[1];
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[0],pendingImage:picture},{...items[1],assetId:second.assetId}]}}});assert.notEqual(saved.preparationData[category].items[0].assetId,first.assetId);assert.equal(saved.preparationData[category].items[0].itemId,first.itemId);assert.equal(saved.preparationData[category].items[0].createdAt,first.createdAt);assert.equal(saved.preparationData[category].items[1].assetId,second.assetId);
 await assert.rejects(f.service.asset(p.projectId,first.assetId),e=>e.code==='PROJECT_ASSET_NOT_FOUND');assert.equal((await f.service.asset(p.projectId,second.assetId)).headers.get('Content-Type'),'image/png');
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[1],assetId:second.assetId}]}}});assert.equal(saved.preparationData[category].items.length,1);assert.equal(saved[category+'Assets'].count,1);
 saved=await f.prepare(p.projectId,{data:{[category]:{items:[{...items[1],name:'',assetId:second.assetId}]}}});assert.equal(saved.preparationReadiness.categories[category].valid,false);
});
test('staffing history, active membership and evidence are required; join/leave times are Worker-controlled mid-project',async()=>{
 const f=fixture(),p=await f.service.create(baseInput);const staff=async members=>f.service.staffing(p.projectId,{expectedRevision:(await f.service.get(p.projectId)).staffingData.revision,data:{members},actor:'Supervisor'});
 let saved=await f.prepare(p.projectId,{data:{staffingResources:{status:'Ready',evidence:[{pendingImage:picture}]}}});assert.equal(saved.preparationReadiness.categories.staffingResources.valid,false);
 await assert.rejects(staff([{memberId:'one',name:'',status:'Active'}]),e=>e.code==='INVALID_PROJECT_INPUT');await assert.rejects(staff([{memberId:'one',name:'Operator',status:'Active',joinedAt:'fake'}]),e=>e.code==='INVALID_PROJECT_INPUT');
 saved=await staff([{memberId:'one',name:'Operator',status:'Active'},{memberId:'two',name:'Helper',status:'Active'}]);assert.equal(saved.preparationReadiness.categories.staffingResources.valid,true);assert.equal(saved.staffingData.members[0].joinedAt,p.createdAt);assert.equal(saved.staffingData.members[0].leftAt,null);
 const all=readyData();saved=await f.prepare(p.projectId,{data:all});await f.service.status(p.projectId,{projectStatus:'Activating'});await f.service.activate(p.projectId,{activatedBy:'Supervisor',confirmation:true,signature:picture});
 f.setTime('2026-10-01T16:00:00Z');saved=await staff([{memberId:'one',name:'Operator',status:'Left'},{memberId:'two',name:'Helper',status:'Active'},{memberId:'three',name:'Replacement',status:'Active'}]);assert.equal(saved.projectStatus,'In-Progress');assert.equal(saved.staffingData.members.length,3);assert.equal(saved.staffingData.members[0].joinedAt,p.createdAt);assert.equal(saved.staffingData.members[0].leftAt,'2026-10-01T16:00:00.000Z');assert.equal(saved.staffingData.members[2].joinedAt,'2026-10-01T16:00:00.000Z');
 const safe=saved.staffingData.members.map(({memberId,name,status,note})=>({memberId,name,status,note}));await assert.rejects(staff(safe.slice(1)),e=>e.code==='INVALID_PROJECT_INPUT');await assert.rejects(staff(safe.map(m=>m.memberId==='one'?{...m,status:'Active'}:m)),e=>e.code==='INVALID_PROJECT_INPUT');await assert.rejects(staff(safe.map(m=>({...m,leftAt:null}))),e=>e.code==='INVALID_PROJECT_INPUT');
});
test('revision conflicts reject stale checklist/roster saves and concurrent replacement instead of losing changes',async()=>{
 const f=fixture(),p=await f.mutate('create',baseInput);await assert.rejects(f.service.workflow(p.projectId,'preparation',{data:{}}),e=>e.code==='PROJECT_REVISION_CONFLICT');
 const results=await Promise.allSettled(['A','B'].map(note=>f.mutate('preparation',{expectedRevision:0,data:{workstation:{note}}},p.projectId)));assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(results.find(r=>r.status==='rejected').reason.code,'PROJECT_REVISION_CONFLICT');
 await f.service.staffing(p.projectId,{expectedRevision:0,data:{members:[{memberId:'one',name:'Operator',status:'Active'}]}});
 await assert.rejects(f.prepare(p.projectId,{data:{},staffingData:{members:[]},expectedStaffingRevision:0}),e=>e.code==='PROJECT_REVISION_CONFLICT');assert.equal((await f.service.get(p.projectId)).staffingData.members.length,1);
});
test('evidence proxy is project-bound, trusted-origin controlled, safe MIME only and exposes no tokens',async()=>{
 const f=fixture(),p=await f.service.create(baseInput),saved=await f.ready(p.projectId),ref=saved.preparationData.workstation.evidence[0],path=`/api/projects/${p.projectId}/assets/${ref.assetId}`,route=projectRouteFor(path);
 let response=await handleProjects(new Request('http://local'+path,{headers:{Origin:'http://127.0.0.1:5501'}}),f.env,'test',route,{readService:f.service});assert.equal(response.status,200);assert.equal(response.headers.get('X-Content-Type-Options'),'nosniff');assert.equal(response.headers.get('Content-Type'),'image/png');assert.ok((await response.arrayBuffer()).byteLength>0);assert.equal(response.headers.get('Authorization'),null);
 response=await handleProjects(new Request('http://local'+path),f.env,'test',route,{readService:f.service});assert.equal(response.status,403);
 response=await handleProjects(new Request('http://local'+path,{headers:{Referer:'http://127.0.0.1:5501/'}}),f.env,'test',route,{readService:f.service});assert.equal(response.status,200);
 const other=await f.service.create(baseInput);await assert.rejects(f.service.asset(other.projectId,ref.assetId),e=>e.code==='PROJECT_ASSET_NOT_FOUND');await assert.rejects(f.prepare(other.projectId,{data:{workstation:{evidence:[{assetId:ref.assetId}]}}}),e=>e.code==='UNKNOWN_PROJECT_ASSET');await assert.rejects(f.prepare(p.projectId,{data:{productionReport:{evidence:[{assetId:ref.assetId}]}}}),e=>e.code==='UNKNOWN_PROJECT_ASSET');
});
test('picture validation rejects SVG, fake MIME, invalid base64 and oversize input',()=>{
 assert.ok(imageBytes(picture).length>0);for(const raw of [{type:'image/svg+xml',base64:'PHN2Zz4='},{type:'image/png',base64:'YWJj'},{type:'image/jpeg',base64:'%%%'},{type:'image/png',base64:'a'.repeat(8*1024*1024)}])assert.throws(()=>imageBytes(raw),e=>e.code==='INVALID_PROJECT_IMAGE');
});
