 const f=fixture(),p=await f.service.create({...baseInput,targetEndDate:'2026-10-15'});await f.service.update(p.projectId,{note:'Keep history'});assert.equal((await f.service.get(p.projectId)).targetEndDate,'2026-10-15');await f.service.update(p.projectId,{targetEndDate:null});assert.equal((await f.service.get(p.projectId)).targetEndDate,null);
