function fixture(){let stamp=Date.parse('2026-09-30T16:00:00Z');const uploads=new Map(),attachments={upload:async({fileName,mimeType,bytes})=>{const token="private-token-"+uploads.size;uploads.set(token,{file_token:token,name:fileName,type:mimeType,bytes});return token;},download:async token=>new Response(uploads.get(token).bytes,{headers:{"Content-Type":uploads.get(token).type}})};const rows=[],searches=[],stores=new Map(),config={appToken:'base',projectTableId:'projects'};
 const records={listFields:async()=>Object.entries(FIELD_TYPES).map(([field_name,type])=>({field_name,type})),searchRecords:async args=>{searches.push(args);let matches=rows.filter(row=>(args.filter?.conditions||[]).every(c=>c.operator==='isNotEmpty'?Boolean(row.fields[c.field_name]):c.operator==='is'?String(row.fields[c.field_name]??'')===c.value[0]:String(row.fields[c.field_name]??'').includes(c.value[0])));if(args.sort?.length)matches.sort((a,b)=>b.fields[F.createdAt]-a.fields[F.createdAt]);const start=Number(args.pageToken||0),slice=matches.slice(start,start+args.pageSize);return {items:structuredClone(slice),hasMore:start+args.pageSize<matches.length,pageToken:start+args.pageSize<matches.length?String(start+args.pageSize):''};},createRecord:async({fields})=>{await Promise.resolve();const row={record_id:`rec${rows.length+1}`,fields:structuredClone(fields)};rows.push(row);return structuredClone(row);},updateRecord:async({recordId,fields})=>{await Promise.resolve();const row=rows.find(row=>row.record_id===recordId);const expanded=structuredClone(fields);for(const [key,value] of Object.entries(expanded))if(Array.isArray(value))expanded[key]=value.map(file=>file.file_token?{...uploads.get(file.file_token),bytes:undefined}:file);Object.assign(row.fields,expanded);return structuredClone(row);}};
 function storage(scope){if(!stores.has(scope))stores.set(scope,new Map());const map=stores.get(scope);return {get:async key=>map.get(key),put:async(key,value)=>map.set(key,value)};}
 const service=createProjectService(config,records,{storage:storage('direct'),attachments,now:()=>stamp}),objects=new Map();
 const env={ALLOWED_ORIGINS:'http://127.0.0.1:5501',PROJECTS:{idFromName:name=>name,get:name=>{if(!objects.has(name)){const s=storage(name),svc=createProjectService(config,records,{storage:s,attachments,now:()=>stamp});objects.set(name,new ProjectCoordinator({storage:s},{},{service:svc}));}return objects.get(name);}}};
 async function mutate(action,input,projectId){const response=await mutateProject(env,action,input,projectId,{now:()=>stamp}),body=await response.json();if(!body.ok)throw Object.assign(Error(body.error.message),{code:body.error.code,status:response.status});return body.data;}
 const prepare=async(id,input)=>service.workflow(id,'preparation',{expectedRevision:(await service.get(id)).preparationData.revision,...input});
 const ready=async id=>prepare(id,{data:readyData(),expectedStaffingRevision:(await service.get(id)).staffingData.revision,staffingData:{members:[{memberId:'STAFF-1',name:'Operator',status:'Active'}]}});
 return {rows,searches,records,attachments,service,env,objects,stores,uploads,prepare,ready,mutate,setTime:time=>stamp=Date.parse(time)};
}
