 assert.equal((await f.service.list({projectStatus:'Preparing',projectType:'Refurbishment',projectOwner:'Alex',search:'Second'})).items.length,1);assert.ok(f.searches.every(q=>q.pageSize<=100));assert.ok(!('dailyReportData' in first.items[0]));await assert.rejects(f.service.list({limit:101}),e=>e.code==='INVALID_PROJECT_INPUT');
